FeatureScript 3083;
import(path : "onshape/std/common.fs", version : "3083.0");

// Generated by fsgen (paste export). Paste into a Feature Studio, then add the feature
// to a Part Studio from the toolbar. Parameters appear in the feature dialog.

// Midpoint of an arc from its endpoints; k = tan(sweep / 4) keeps the arc's sweep when parameters change.
function arcMid(a is Vector, b is Vector, k is number) returns Vector
{
    var d = b - a;
    return (a + b) / 2 + vector(d[1], -d[0]) * (k / 2);
}

annotation { "Feature Type Name" : "Bracket" }
export const bracket = defineFeature(function(context is Context, id is Id, definition is map)
    precondition
    {
        annotation { "Name" : "Thickness" }
        isLength(definition.thickness, { (millimeter) : [0, 12, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Base length" }
        isLength(definition.baseLength, { (millimeter) : [0, 60, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Foot height" }
        isLength(definition.footHeight, { (millimeter) : [0, 8, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Pedestal width" }
        isLength(definition.pedestalWidth, { (millimeter) : [0, 36, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Pedestal height" }
        isLength(definition.pedestalHeight, { (millimeter) : [0, 14, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Bore height" }
        isLength(definition.boreHeight, { (millimeter) : [0, 29.25, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Bore diameter" }
        isLength(definition.boreDiameter, { (millimeter) : [0, 25.5, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Ring wall" }
        isLength(definition.ringWall, { (millimeter) : [0, 4, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Slot width" }
        isLength(definition.slotWidth, { (millimeter) : [0, 2, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Ear thickness" }
        isLength(definition.earThickness, { (millimeter) : [0, 3, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Ear top height" }
        isLength(definition.earTopHeight, { (millimeter) : [0, 52.9615, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Screw hole diameter" }
        isLength(definition.screwHoleDiameter, { (millimeter) : [0, 3.4, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Clamp hole height" }
        isLength(definition.clampHoleHeight, { (millimeter) : [0, 49.2, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Mount hole spacing" }
        isLength(definition.mountHoleSpacing, { (millimeter) : [0, 48, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Web fillet radius" }
        isLength(definition.webFilletRadius, { (millimeter) : [0, 3, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Ear round radius" }
        isLength(definition.earRoundRadius, { (millimeter) : [0, 1, 10000] } as LengthBoundSpec);
    }
    {
    // Base sketch
    var baseSketchSk = newSketchOnPlane(context, id + "baseSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skLineSegment(baseSketchSk, "outline_0", { "start" : vector(-definition.baseLength / 2, (0 * millimeter)), "end" : vector(definition.baseLength / 2, (0 * millimeter)) });
    skLineSegment(baseSketchSk, "outline_1", { "start" : vector(definition.baseLength / 2, (0 * millimeter)), "end" : vector(definition.baseLength / 2, definition.footHeight) });
    skLineSegment(baseSketchSk, "outline_2", { "start" : vector(definition.baseLength / 2, definition.footHeight), "end" : vector(definition.pedestalWidth / 2, definition.footHeight) });
    skLineSegment(baseSketchSk, "outline_3", { "start" : vector(definition.pedestalWidth / 2, definition.footHeight), "end" : vector(definition.pedestalWidth / 2, definition.pedestalHeight) });
    skLineSegment(baseSketchSk, "outline_4", { "start" : vector(definition.pedestalWidth / 2, definition.pedestalHeight), "end" : vector(-definition.pedestalWidth / 2, definition.pedestalHeight) });
    skLineSegment(baseSketchSk, "outline_5", { "start" : vector(-definition.pedestalWidth / 2, definition.pedestalHeight), "end" : vector(-definition.pedestalWidth / 2, definition.footHeight) });
    skLineSegment(baseSketchSk, "outline_6", { "start" : vector(-definition.pedestalWidth / 2, definition.footHeight), "end" : vector(-definition.baseLength / 2, definition.footHeight) });
    skLineSegment(baseSketchSk, "outline_7", { "start" : vector(-definition.baseLength / 2, definition.footHeight), "end" : vector(-definition.baseLength / 2, (0 * millimeter)) });
    skSolve(baseSketchSk);
    // Base
    opExtrude(context, id + "base" + "tool", { "entities" : qSketchRegion(id + "baseSketch"), "direction" : vector(-0, 1, -0), "endBound" : BoundingType.BLIND, "endDepth" : definition.thickness });
    // Clamp ring and ears sketch
    var clampRingAndEarsSketchSk = newSketchOnPlane(context, id + "clampRingAndEarsSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skCircle(clampRingAndEarsSketchSk, "ring", { "center" : vector((0 * millimeter), definition.boreHeight), "radius" : definition.boreDiameter / 2 + definition.ringWall });
    skLineSegment(clampRingAndEarsSketchSk, "ears_bottom", { "start" : vector(-(definition.slotWidth / 2 + definition.earThickness), definition.boreHeight), "end" : vector(definition.slotWidth / 2 + definition.earThickness, definition.boreHeight) });
    skLineSegment(clampRingAndEarsSketchSk, "ears_right", { "start" : vector(definition.slotWidth / 2 + definition.earThickness, definition.boreHeight), "end" : vector(definition.slotWidth / 2 + definition.earThickness, definition.earTopHeight) });
    skLineSegment(clampRingAndEarsSketchSk, "ears_top", { "start" : vector(definition.slotWidth / 2 + definition.earThickness, definition.earTopHeight), "end" : vector(-(definition.slotWidth / 2 + definition.earThickness), definition.earTopHeight) });
    skLineSegment(clampRingAndEarsSketchSk, "ears_left", { "start" : vector(-(definition.slotWidth / 2 + definition.earThickness), definition.earTopHeight), "end" : vector(-(definition.slotWidth / 2 + definition.earThickness), definition.boreHeight) });
    skSolve(clampRingAndEarsSketchSk);
    // Clamp ring and ears
    opExtrude(context, id + "clampRingAndEars" + "tool", { "entities" : qSketchRegion(id + "clampRingAndEarsSketch"), "direction" : vector(-0, 1, -0), "endBound" : BoundingType.BLIND, "endDepth" : definition.thickness });
    opBoolean(context, id + "clampRingAndEars" + "bool", { "tools" : qUnion([qSubtraction(qCreatedBy(id + "base", EntityType.BODY), qCreatedBy(id + "clampRingAndEars" + "tool", EntityType.BODY)), qCreatedBy(id + "clampRingAndEars" + "tool", EntityType.BODY)]), "operationType" : BooleanOperationType.UNION });
    // Bore and split sketch
    var boreAndSplitSketchSk = newSketchOnPlane(context, id + "boreAndSplitSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skCircle(boreAndSplitSketchSk, "bore", { "center" : vector((0 * millimeter), definition.boreHeight), "radius" : definition.boreDiameter / 2 });
    skLineSegment(boreAndSplitSketchSk, "split_bottom", { "start" : vector(-definition.slotWidth / 2, definition.boreHeight), "end" : vector(definition.slotWidth / 2, definition.boreHeight) });
    skLineSegment(boreAndSplitSketchSk, "split_right", { "start" : vector(definition.slotWidth / 2, definition.boreHeight), "end" : vector(definition.slotWidth / 2, definition.earTopHeight + (1 * millimeter)) });
    skLineSegment(boreAndSplitSketchSk, "split_top", { "start" : vector(definition.slotWidth / 2, definition.earTopHeight + (1 * millimeter)), "end" : vector(-definition.slotWidth / 2, definition.earTopHeight + (1 * millimeter)) });
    skLineSegment(boreAndSplitSketchSk, "split_left", { "start" : vector(-definition.slotWidth / 2, definition.earTopHeight + (1 * millimeter)), "end" : vector(-definition.slotWidth / 2, definition.boreHeight) });
    skSolve(boreAndSplitSketchSk);
    // Bore and clamp split
    opExtrude(context, id + "boreAndClampSplit" + "tool", { "entities" : qSketchRegion(id + "boreAndSplitSketch"), "direction" : vector(-0, 1, -0), "endBound" : BoundingType.THROUGH_ALL });
    opBoolean(context, id + "boreAndClampSplit" + "bool", { "tools" : qCreatedBy(id + "boreAndClampSplit" + "tool", EntityType.BODY), "targets" : qSubtraction(qCreatedBy(id + "base", EntityType.BODY), qCreatedBy(id + "boreAndClampSplit" + "tool", EntityType.BODY)), "operationType" : BooleanOperationType.SUBTRACTION });
    // Clamp screw hole sketch
    var clampScrewHoleSketchSk = newSketchOnPlane(context, id + "clampScrewHoleSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(1, 0, 0), vector(0, 1, 0)) });
    skCircle(clampScrewHoleSketchSk, "hole", { "center" : vector(definition.thickness / 2, definition.clampHoleHeight), "radius" : definition.screwHoleDiameter / 2 });
    skSolve(clampScrewHoleSketchSk);
    // Clamp screw hole
    opExtrude(context, id + "clampScrewHole" + "tool", { "entities" : qSketchRegion(id + "clampScrewHoleSketch"), "direction" : vector(1, 0, 0), "endBound" : BoundingType.BLIND, "endDepth" : (2 * (definition.slotWidth / 2 + definition.earThickness) + (2 * millimeter)) / 2, "startBound" : BoundingType.BLIND, "startDepth" : (2 * (definition.slotWidth / 2 + definition.earThickness) + (2 * millimeter)) / 2 });
    opBoolean(context, id + "clampScrewHole" + "bool", { "tools" : qCreatedBy(id + "clampScrewHole" + "tool", EntityType.BODY), "targets" : qSubtraction(qCreatedBy(id + "base", EntityType.BODY), qCreatedBy(id + "clampScrewHole" + "tool", EntityType.BODY)), "operationType" : BooleanOperationType.SUBTRACTION });
    // Mounting holes sketch
    var mountingHolesSketchSk = newSketchOnPlane(context, id + "mountingHolesSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(mountingHolesSketchSk, "holeL", { "center" : vector(-definition.mountHoleSpacing / 2, definition.thickness / 2), "radius" : definition.screwHoleDiameter / 2 });
    skCircle(mountingHolesSketchSk, "holeR", { "center" : vector(definition.mountHoleSpacing / 2, definition.thickness / 2), "radius" : definition.screwHoleDiameter / 2 });
    skSolve(mountingHolesSketchSk);
    // Mounting holes
    opExtrude(context, id + "mountingHoles" + "tool", { "entities" : qSketchRegion(id + "mountingHolesSketch"), "direction" : vector(0, 0, 1), "endBound" : BoundingType.THROUGH_ALL });
    opBoolean(context, id + "mountingHoles" + "bool", { "tools" : qCreatedBy(id + "mountingHoles" + "tool", EntityType.BODY), "targets" : qSubtraction(qCreatedBy(id + "base", EntityType.BODY), qCreatedBy(id + "mountingHoles" + "tool", EntityType.BODY)), "operationType" : BooleanOperationType.SUBTRACTION });
    // Web fillets
    opFillet(context, id + "webFillets", { "entities" : qIntersection([qAdjacent(qGeometry(qCreatedBy(id + "clampRingAndEars", EntityType.FACE), GeometryType.CYLINDER), AdjacencyType.EDGE, EntityType.EDGE), qAdjacent(qParallelPlanes(qCreatedBy(id + "base", EntityType.FACE), vector(0.0, 0.0, 1.0)), AdjacencyType.EDGE, EntityType.EDGE)]), "radius" : definition.webFilletRadius });
    // Ear top rounds
    opFillet(context, id + "earTopRounds", { "entities" : qParallelPlanes(qCreatedBy(id + "clampRingAndEars", EntityType.FACE), vector(0.0, 0.0, 1.0)), "radius" : definition.earRoundRadius });
    // remove the construction sketches and curves
    opDeleteBodies(context, id + "cleanupSketches", { "entities" : qUnion([qCreatedBy(id + "baseSketch", EntityType.BODY), qCreatedBy(id + "clampRingAndEarsSketch", EntityType.BODY), qCreatedBy(id + "boreAndSplitSketch", EntityType.BODY), qCreatedBy(id + "clampScrewHoleSketch", EntityType.BODY), qCreatedBy(id + "mountingHolesSketch", EntityType.BODY)]) });
    });
